+        }
+    });
+    assert!(matches!(outcome, Err(CellSplitExecutionErrorV1::Ambiguous)));
+    assert_eq!(checks, 4, "final post-native admission must run");
+    assert_eq!(state.borrow().executions, 1);
+    assert_eq!(owner.completed_steps(), 0);
